const fluorFlag = (v = "") => {
  const t = String(v);
  if (/yellow/i.test(t)) return `${t} fluorescence`;
  if (/^(strong|very strong)/i.test(t)) return `${t} fluorescence`;
  return null;
};

/* ==================================================================== */
/*  Round brilliant, drawn to plan                                      */
/* ==================================================================== */
function Brilliant({ size = 40, stroke = T.gold, width = 0.9, opacity = 1 }) {
  const R = 46, C = 50, rt = 16.5;
  const pt = (deg, r) => [C + r * Math.cos((deg * Math.PI) / 180), C + r * Math.sin((deg * Math.PI) / 180)];
  const table = Array.from({ length: 8 }, (_, k) => pt(22.5 + 45 * k, rt).map((n) => n.toFixed(2)).join(",")).join(" ");
  const lines = [];
  for (let k = 0; k < 8; k++) {
    const a = 22.5 + 45 * k;
    lines.push([pt(a, rt), pt(a, R)]);
    const b = 45 * k;
    lines.push([pt(b, rt * Math.cos(Math.PI / 8)), pt(b, R)]);
  }
  return (
    <svg viewBox="0 0 100 100" width={size} height={size} style={{ opacity, display: "block" }} aria-hidden="true">
      <g fill="none" stroke={stroke} strokeWidth={width} strokeLinejoin="round">
        <circle cx={C} cy={C} r={R} />
        <circle cx={C} cy={C} r={R * 0.84} strokeWidth={width * 0.7} />
        <polygon points={table} />
        {lines.map(([a, b], i) => (
          <line key={i} x1={a[0].toFixed(2)} y1={a[1].toFixed(2)} x2={b[0].toFixed(2)} y2={b[1].toFixed(2)} strokeWidth={width * 0.7} />
        ))}
      </g>
    </svg>
  );
}

/* An atelier working sheet: plan, profile, and the numbers pencilled in */
